testcase.name:
test_independent_oracle_rejects_behavioral_mutants[#ifndef TEST_CRC_H
#define TEST_CRC_H
#include "forge_crc_device.h"
static inline void LL_CRC_Write_IDR(CRC_TypeDef *CRCx, uint32_t InData)
{
 CRCx->IDR = InData & 0xFFU;
}
static inline uint32_t LL_CRC_Read_IDR(const CRC_TypeDef *CRCx)
{
 return CRCx->IDR;
}
#endif
]

test_independent_oracle_rejects_behavioral_mutants[#ifndef TEST_CRC_H
#define TEST_CRC_H
#include "forge_crc_device.h"
static inline void LL_CRC_Write_IDR(CRC_TypeDef *CRCx, uint32_t InData)
{
 CRCx->IDR = InData;
}
static inline uint32_t LL_CRC_Read_IDR(const CRC_TypeDef *CRCx)
{
 return CRCx->IDR & 0xFFU;
}
#endif
]

test_independent_oracle_rejects_behavioral_mutants[#ifndef TEST_CRC_H
#define TEST_CRC_H
#include "forge_crc_device.h"
static inline void LL_CRC_Write_IDR(CRC_TypeDef *CRCx, uint32_t InData)
{
 CRCx->IDR = InData; CRCx->DR = 0U;
}
static inline uint32_t LL_CRC_Read_IDR(const CRC_TypeDef *CRCx)
{
 return CRCx->IDR;
}
#endif
]

test_independent_oracle_rejects_behavioral_mutants[#ifndef TEST_CRC_H
#define TEST_CRC_H
#include "forge_crc_device.h"
static inline void LL_CRC_Write_IDR(CRC_TypeDef *CRCx, uint32_t InData)
{
 CRCx->IDR = InData;
}
static inline uint32_t LL_CRC_Read_IDR(const CRC_TypeDef *CRCx)
{
